parameters.jsCode:
/**
 * Validation Assessment + Restore Application
 *
 * Input:
 *   Parsed assessment from "Parse AI Assessment"
 *
 * Source:
 *   Original application from "Normalize Application"
 *
 * Output:
 *   Original application fields + validated assessment fields
 */

const assessment = { ...$input.item.json };

// Retrieve the original application data.
// This assumes the workflow processes one application per item
// and item linking is preserved between nodes.
const application = $('Normalize Application').item.json;

// --------------------------------------------------
// 1. Validate original application data
// --------------------------------------------------

const requiredApplicationFields = [
  'application_id',
  'full_name',
  'email',
  'job_id',
  'position'
];

const missingApplicationFields = requiredApplicationFields.filter(
  field =>
    application[field] === undefined ||
    application[field] === null ||
    String(application[field]).trim() === ''
);

if (missingApplicationFields.length > 0) {
  throw new Error(
    'Original application is missing required fields: ' +
    missingApplicationFields.join(', ')
  );
}

// --------------------------------------------------
// 2. Validate essential assessment fields
// --------------------------------------------------

const requiredAssessmentFields = [
  'evidence_status',
  'evidence_score',
  'evidence_gaps',
  'follow_up_questions',
  'recruiter_review_required'
];

const missingAssessmentFields = requiredAssessmentFields.filter(
  field =>
    !Object.prototype.hasOwnProperty.call(assessment, field)
);

if (missingAssessmentFields.length > 0) {
  throw new Error(
    'Assessment is missing required fields: ' +
    missingAssessmentFields.join(', ')
  );
}

if (!['provided', 'partial', 'missing'].includes(assessment.evidence_status)) {
  throw new Error(
    'Invalid evidence_status: expected provided, partial, or missing.'
  );
}

if (
  !Number.isInteger(assessment.evidence_score) ||
  assessment.evidence_score < 0 ||
  assessment.evidence_score > 5
) {
  throw new Error('evidence_score must be an integer between 0 and 5.');
}

for (const field of ['evidence_gaps', 'follow_up_questions']) {
  if (
    !Array.isArray(assessment[field]) ||
    !assessment[field].every(value => typeof value === 'string')
  ) {
    throw new Error(field + ' must be an array of strings.');
  }
}

// --------------------------------------------------
// 3. Normalize optional assessment fields
// --------------------------------------------------

if (!Array.isArray(assessment.strengths)) {
  assessment.strengths = [];
}

if (!assessment.strengths.every(value => typeof value === 'string')) {
  throw new Error('strengths must be an array of strings.');
}

if (typeof assessment.assessment_summary !== 'string') {
  assessment.assessment_summary =
    'The AI did not provide an assessment summary. Recruiter review is required.';
}

if (typeof assessment.recruiter_review_required !== 'boolean') {
  throw new Error('recruiter_review_required must be a boolean.');
}

if (typeof assessment.recommendation !== 'string') {
  assessment.recommendation = 'REQUIRES_RECRUITER_REVIEW';
}

// --------------------------------------------------
// 4. Check that assessment belongs to this application
// --------------------------------------------------

if (
  assessment.application_id &&
  String(assessment.application_id) !== String(application.application_id)
) {
  throw new Error(
    'Application ID mismatch: the assessment does not match the original application.'
  );
}

if (
  assessment.job_id &&
  String(assessment.job_id) !== String(application.job_id)
) {
  throw new Error(
    'Job ID mismatch: the assessment does not match the original application.'
  );
}

// --------------------------------------------------
// 5. Restore original application fields
// --------------------------------------------------

// Original application data is spread first.
// Assessment fields are then added, without allowing
// assessment values to overwrite core application details.

const output = {
  ...application,

  assessment_position: assessment.position ?? application.position,
  evidence_score: assessment.evidence_score,
  evidence_status: assessment.evidence_status,
  strengths: assessment.strengths,
  evidence_gaps: assessment.evidence_gaps,
  follow_up_questions: assessment.follow_up_questions,
  assessment_summary: assessment.assessment_summary,
  recruiter_review_required: assessment.recruiter_review_required,
  recommendation: assessment.recommendation,

  assessment_parse_status:
    assessment.assessment_parse_status ?? 'success',

  assessment_warnings:
    Array.isArray(assessment.assessment_warnings)
      ? assessment.assessment_warnings
      : [],

  assessment_validation_status: 'validated'
};

// Return one item to the next node.
return {
  json: output
};

