parameters.jsCode:
const input = $input.item.json;

// 1. Extract the AI Agent response.
const raw = input.output ?? input.text ?? input.response ?? input.result;

if (raw === undefined || raw === null) {
  throw new Error('No AI response found in output, text, response, or result.');
}

// 2. Parse the response.
let assessment;

if (typeof raw === 'string') {
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    assessment = JSON.parse(cleaned);
  } catch (error) {
    throw new Error('AI response is invalid JSON: ' + error.message);
  }
} else if (
  typeof raw === 'object' &&
  !Array.isArray(raw)
) {
  assessment = raw;
} else {
  throw new Error('AI response must be a JSON object or JSON string.');
}

// 3. Validate essential fields.
const requiredFields = [
  'application_id',
  'job_id',
  'position',
  'evidence_score',
  'evidence_status',
  'evidence_gaps',
  'follow_up_questions',
  'recruiter_review_required'
];

const missing = requiredFields.filter(
  field => !Object.prototype.hasOwnProperty.call(assessment, field)
);

if (missing.length > 0) {
  throw new Error('AI assessment is missing required fields: ' + missing.join(', '));
}

// 4. Validate values and types.
if (!['provided', 'partial', 'missing'].includes(assessment.evidence_status)) {
  throw new Error('evidence_status must be provided, partial, or missing.');
}

if (
  !Number.isInteger(assessment.evidence_score) ||
  assessment.evidence_score < 0 ||
  assessment.evidence_score > 5
) {
  throw new Error('evidence_score must be an integer from 0 to 5.');
}

for (const field of ['evidence_gaps', 'follow_up_questions']) {
  if (
    !Array.isArray(assessment[field]) ||
    !assessment[field].every(value => typeof value === 'string')
  ) {
    throw new Error(field + ' must be an array of strings.');
  }
}

if (typeof assessment.recruiter_review_required !== 'boolean') {
  throw new Error('recruiter_review_required must be a boolean.');
}

// 5. Safely handle optional fields.
// Do not fabricate strengths or summaries if the AI omitted them.
if (!Array.isArray(assessment.strengths)) {
  assessment.strengths = [];
}

if (!assessment.strengths.every(value => typeof value === 'string')) {
  throw new Error('strengths must be an array of strings.');
}

if (typeof assessment.assessment_summary !== 'string') {
  assessment.assessment_summary =
    'The AI did not provide an assessment summary. Recruiter review is required.';
}

// 6. Mark the assessment for human review if information is incomplete.
const missingOptionalFields = [];

if (!Object.prototype.hasOwnProperty.call(JSON.parse(JSON.stringify(assessment)), 'strengths')) {
  missingOptionalFields.push('strengths');
}

if (
  assessment.assessment_summary.startsWith(
    'The AI did not provide an assessment summary.'
  )
) {
  missingOptionalFields.push('assessment_summary');
}

if (missingOptionalFields.length > 0) {
  assessment.recruiter_review_required = true;
}

// 7. Return the normalized assessment.
return {
  json: {
    ...assessment,
    assessment_parse_status: 'success',
    assessment_warnings: missingOptionalFields
  }
};
